Bugs: the pods share group pricing-api, so subscribe() gives each partition to one pod and each pod holds about a third of the SKUs; auto-commit stores positions, so a restarted pod resumes near the end (earliest applies only without a committed offset); a null value is a delete; ready is set before anything is loaded.
public void run() {
  Properties p = new Properties();
  p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, System.getenv("KAFKA_BOOTSTRAP"));
  p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
  p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
  // no group.id: no group, no commits
  try (KafkaConsumer<String, String> c = new KafkaConsumer<>(p)) {
    List<TopicPartition> tps = c.partitionsFor("prices").stream()
        .map(i -> new TopicPartition(i.topic(), i.partition())).toList();
    c.assign(tps);
    c.seekToBeginning(tps);
    Map<TopicPartition, Long> end = c.endOffsets(tps);
    while (running) {
      for (ConsumerRecord<String, String> r : c.poll(Duration.ofMillis(500))) {
        if (r.value() == null) cache.remove(r.key());
        else cache.put(r.key(), Price.parse(r.value()));
      }
      if (!ready.get() && tps.stream().allMatch(tp -> c.position(tp) >= end.get(tp)))
        ready.set(true);
    }
  }
}
Each pod reads all partitions from the start, applies tombstones, and turns ready only when its positions reach the end offsets taken at startup; then it keeps applying updates. Keep the initial load well under delete.retention.ms (default 24 h), or tombstones can be missed.

The quick version looked at replicas instead of the ISR (a partition whose ISR is already 2 of 3 drops to 1), hard-coded 2 (topics override min.insync.replicas), and skipped internal topics such as __consumer_offsets and __transaction_state (min ISR from transaction.state.log.min.isr, default 2, so transactions can stall too). While the broker is down, acks=all producers on such partitions get NotEnoughReplicas, and new records stay invisible to consumers whatever the acks.
import sys
from confluent_kafka import TopicCollection
from confluent_kafka.admin import AdminClient, ConfigResource, ResourceType

def at_risk(bootstrap, broker):
    admin = AdminClient({"bootstrap.servers": bootstrap})
    names = list(admin.list_topics(timeout=30).topics)
    descs = {n: f.result() for n, f in admin.describe_topics(TopicCollection(names)).items()}
    res = [ConfigResource(ResourceType.TOPIC, n) for n in names]
    min_isr = {r.name: int(f.result()["min.insync.replicas"].value)
               for r, f in admin.describe_configs(res).items()}
    out = []
    for name, d in descs.items():
        for p in d.partitions:
            isr = [n.id for n in p.isr]
            if broker in isr and len(isr) - 1 < min_isr[name]:
                out.append((name, p.id, isr, min_isr[name]))
    return out

if __name__ == "__main__":
    rows = at_risk(sys.argv[1], int(sys.argv[2]))
    for name, pid, isr, m in rows:
        print(f"{name}-{pid} isr={isr} min.insync.replicas={m}")
    sys.exit(1 if rows else 0)
It only reads (list_topics, describe_topics, describe_configs). Run it right before stopping the broker; the ISR changes.

Strimzi ignores plugin.path in spec.config (it manages the plugin path). With plugin.discovery=service_load the worker only finds plugins listed in a ServiceLoader manifest: add src/main/resources/META-INF/services/org.apache.kafka.connect.source.SourceConnector containing com.example.ticket.TicketSourceConnector.

public class TicketSourceConnector extends SourceConnector {
  private Map<String,String> props;
  public void start(Map<String,String> p) { props = p; }
  public Class<? extends Task> taskClass() { return TicketSourceTask.class; }
  public List<Map<String,String>> taskConfigs(int maxTasks) {   // tasksMax: 2
    List<Map<String,String>> cfgs = new ArrayList<>();
    for (String r : List.of("eu", "us")) { Map<String,String> c = new HashMap<>(props); c.put("region", r); cfgs.add(c); }
    return cfgs;
  }
  public void stop() {}
  public ConfigDef config() { return CONFIG_DEF; }
}

public class TicketSourceTask extends SourceTask {
  private Map<String,String> part; private String cursor, topic; private TicketApi api;
  public void start(Map<String,String> p) {
    topic = p.get("topic"); api = new TicketApi(p.get("api.url"));
    part = Map.of("region", p.get("region"));
    Map<String,Object> off = context.offsetStorageReader().offset(part);
    cursor = off == null ? "" : (String) off.get("cursor");
  }
  public List<SourceRecord> poll() throws InterruptedException {
    Page page = api.changes(part.get("region"), cursor, 500);
    if (page.items().isEmpty()) { Thread.sleep(5000); return null; }
    List<SourceRecord> out = new ArrayList<>();
    for (int i = 0; i < page.items().size(); i++) {
      String o = i == page.items().size() - 1 ? page.nextCursor() : cursor;
      out.add(new SourceRecord(part, Map.of("cursor", o), topic, Schema.STRING_SCHEMA, page.items().get(i).json()));
    }
    cursor = page.nextCursor();
    return out;
  }
  public synchronized void stop() { api.close(); }
}

