Two separate problems. Discovery: with service_load the worker no longer scans JARs, so ship a file META-INF/services/org.apache.kafka.connect.source.SourceConnector listing the connector class; plugin.path cannot be set on Strimzi. Resume: drop the /tmp file and use Connect's offsets.

// connector
public List<Map<String,String>> taskConfigs(int maxTasks) {
  return List.of(withRegion(props, "eu"), withRegion(props, "us"));
}
// task
private final AtomicBoolean stopping = new AtomicBoolean();
public void start(Map<String,String> p) {
  region = p.get("region");
  Map<String,Object> o = context.offsetStorageReader().offset(Map.of("region", region));
  cursor = o == null ? "" : (String) o.get("cursor");
}
public List<SourceRecord> poll() throws InterruptedException {
  Page pg = api.changes(region, cursor, 500);
  if (pg.items().isEmpty()) { if (!stopping.get()) Thread.sleep(3000); return List.of(); }
  List<Ticket> items = pg.items();
  List<SourceRecord> recs = new ArrayList<>();
  for (int i = 0; i < items.size(); i++) {
    String resume = i < items.size() - 1 ? cursor : pg.nextCursor(); // only the page's last record moves the offset
    recs.add(new SourceRecord(Map.of("region", region), Map.of("cursor", resume), topic, Schema.STRING_SCHEMA, items.get(i).json()));
  }
  cursor = pg.nextCursor();
  return recs;
}
public void stop() { stopping.set(true); }

