import json
from confluent_kafka.admin import (AdminClient, NewTopic, NewPartitions, ConfigResource,
    ConfigEntry, AlterConfigOpType, ResourceType)

def managed(path):  # kubectl get kafkatopics -n kafka -o json
    return {i["spec"].get("topicName") or i["metadata"]["name"] for i in json.load(open(path))["items"]}

def sync(admin, customers, owned_by_kafkatopic):
    md = admin.list_topics(timeout=30)
    new, parts, cfgs = [], [], []
    for c in customers:
        name = f"cust-{c.id}-events"
        if name in owned_by_kafkatopic:
            print(f"{name}: owned by a KafkaTopic, change its spec"); continue
        t = md.topics.get(name)
        if t is None:
            new.append(NewTopic(name, num_partitions=c.partitions, replication_factor=3,
                                config={"retention.ms": str(c.retention_ms)}))
            continue
        if len(t.partitions) < c.partitions:
            parts.append(NewPartitions(name, c.partitions))
        cfgs.append(ConfigResource(ResourceType.TOPIC, name, incremental_configs=[
            ConfigEntry("retention.ms", str(c.retention_ms), incremental_operation=AlterConfigOpType.SET)]))
    futs = {}
    for call, arg in ((admin.create_topics, new), (admin.create_partitions, parts), (admin.incremental_alter_configs, cfgs)):
        if arg: futs.update(call(arg))
    for k, f in futs.items():
        try: f.result()
        except Exception as e: print(f"{k}: {e}")

The Topic Operator reverts direct changes to topics that have a KafkaTopic, so the job skips them; match on spec.topicName, since cust-ACME_EU-events is not a valid Kubernetes name. alter_configs reset every unspecified setting to its default; incremental SET changes retention.ms only. Partitions only grow: Kafka cannot reduce them. Restore cust-4711-events once: kafka-configs.sh --alter --add-config 'cleanup.policy=[compact,delete],min.insync.replicas=2'.

Each pod must advertise its own address, and the handler routes by key.

// POD_IP from the downward API (fieldPath: status.podIP)
String self = System.getenv("POD_IP") + ":8080";
props.put(StreamsConfig.APPLICATION_SERVER_CONFIG, self);
HostInfo me = HostInfo.buildFromEndpoint(self);

record Reply(int status, Long balance) {}

Reply balance(String accountId, boolean forwarded) {
  KeyQueryMetadata md = streams.queryMetadataForKey(
      "account-balances", accountId, Serdes.String().serializer());
  if (md == null || KeyQueryMetadata.NOT_AVAILABLE.equals(md)) return new Reply(503, null);
  HostInfo owner = md.activeHost();
  if (!owner.equals(me)) {
    if (forwarded) return new Reply(503, null);   // at most one hop
    return forwardGet(owner.host(), owner.port(),  // your HTTP client
        "/balances/" + accountId + "?forwarded=true");
  }
  try {
    ReadOnlyKeyValueStore<String, Long> store = streams.store(
        StoreQueryParameters.fromNameAndType("account-balances",
            QueryableStoreTypes.<String, Long>keyValueStore()));
    Long v = store.get(accountId);
    return v == null ? new Reply(404, null) : new Reply(200, v);
  } catch (InvalidStateStoreException e) {      // migrating or restoring
    return new Reply(503, null);
  }
}

metadataForKey and store(String, QueryableStoreType) were removed in 3.0; queryMetadataForKey with KeyQueryMetadata.activeHost() and store(StoreQueryParameters) replace them. application.server must differ per pod; the Service name would make every pod look like the owner. 503 during rebalances lets callers retry.

The flush() after each produce() is the limit: produce() only queues the message, and flush() blocks until everything queued is delivered, so you pay a broker round trip per message and batch.size never matters. Queue, serve callbacks with poll(0), flush once at the end.

import json, logging
from confluent_kafka import Producer

log = logging.getLogger("clicks-ingest")
p = Producer({
    "bootstrap.servers": "kafka-bootstrap:9092",
    "client.id": "clicks-ingest",
    "enable.idempotence": True,   # acks=all; retries cannot duplicate or reorder
    "linger.ms": 20,              # let per-partition batches fill
    "compression.type": "lz4",
})

def on_delivery(err, msg):
    if err is not None:
        log.error("delivery failed key=%s err=%s", msg.key(), err)

def send(event):
    key = event["user_id"].encode()
    value = json.dumps(event).encode()
    while True:
        try:
            p.produce("clicks", key=key, value=value, on_delivery=on_delivery)
            break
        except BufferError:        # local queue full
            p.poll(0.5)            # let deliveries complete, then retry
    p.poll(0)                      # serve delivery callbacks

try:
    for event in queue_reader():
        send(event)
finally:
    p.flush(30)

Keying by user_id keeps each user on one partition; idempotence keeps that order through retries. batch.size is only an upper bound; linger.ms is what lets a batch collect records.
